INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人助けが大好き！　前向き格闘娘", "ヒヨリ", "トゥインクルウィッシュ", 16, 155, 8, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 100101, "A", 44, 27, 0, "人助け、応援", 2, "獣人族", "東山奈央");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("戦闘のサポートが得意な、心優しい少女", "ユイ", "トゥインクルウィッシュ", 17, 158, 4, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 100201, "O", 47, 5, 0, "料理、人間観察", 2, "ヒューマン", "種田梨沙");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("クールで何事にも真っ直ぐな剣士", "レイ", "トゥインクルウィッシュ", 18, 163, 1, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 100301, "B", 46, 12, 0, "読書、乗馬、お茶", 2, "魔族", "早見沙織");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("探検好きのイタズラっ子", "ミソギ", "リトルリリカル", 9, 128, 8, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 100401, "O", 27, 10, 0, "いたずら、探検", 5, "ヒューマン", "諸星すみれ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ヒーローに憧れる騎士見習いの少女", "マツリ", "王宮騎士団（NIGHTMARE）", 12, 146, 11, "？？？", 100501, "O", 40, 25, 0, "ヒーローごっこ", 8, "獣人族", "下田麻美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("甘え上手なみんなの人気者", "アカリ", "悪魔偽王国軍（ディアボロス）", 13, 150, 11, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 100601, "O", 42, 22, 0, "サックス", 7, "魔族", "浅倉杏美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("プリン大好きゴースト娘", "ミヤコ", "悪魔偽王国軍（ディアボロス）", 14, 130, 1, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 100701, "B", 32, 23, 0, "プリンを食べること", 7, "魔族", "雨宮天");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ボクは誰よりも美しい", "ユキ", "ヴァイスフリューゲル　ランドソル支部", 14, 150, 10, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 100801, "AB", 40, 10, 0, "鏡で自分を見ること", 15, "エルフ", "大空直美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("前世を信じる中二病患者、「疾風の冥姫」", "アンナ", "トワイライトキャラバン", 17, 159, 7, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 100901, "A", 45, 5, 0, "小説執筆", 13, "魔族", "髙野麻美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("マホマホ王国のプリンセス", "マホ", "自警団（カォン）", 16, 155, 9, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 101001, "O", 42, 22, 0, "空想、ぬいぐるみ集め", 10, "獣人族", "内田真礼");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人懐っこくてマシンガントークな妹系少女", "リノ", "ラビリンス", 15, 156, 8, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 101101, "A", 44, 25, 0, "お裁縫", 3, "ヒューマン", "阿澄佳奈");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("みんなのために超能力を使う眠り姫", "ハツネ", "フォレスティエ", 17, 156, 12, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 101201, "A", 46, 24, 0, "妹と遊ぶこと、二度寝、昼寝、早寝", 6, "エルフ", "大橋彩香");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("オタク全開な魔法少女", "ナナカ", "トワイライトキャラバン", 18, 166, 8, "", 101301, "O", 55, 21, 0, "読書、魔法", 13, "魔族", "佳村はるか");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("頭脳明晰な美少女名探偵", "カスミ", "自警団（カォン）", 15, 152, 11, "test", 101401, "AB", 41, 3, 0, "読書、推理", 10, "獣人族", "水瀬いのり");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("母性溢れる優しいみんなの「ミサト先生」", "ミサト", "フォレスティエ", 21, 165, 9, "test", 101501, "O", 54, 5, 0, "絵本作り", 6, "エルフ", "國府田マリ子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("天真爛漫で人気者のカリスマモデル", "スズナ", "ルーセント学院", 17, 167, 4, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 101601, "O", 48, 10, 0, "ファッション", 14, "魔族", "上坂すみれ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("いつでも「なんくるないさ～」な天然娘", "カオリ", "自警団（カォン）", 17, 158, 7, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 101701, "A", 53, 7, 0, "踊り、空手", 10, "獣人族", "高森奈津美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("多くの男性を魅了する無垢な女教師", "イオ", "ルーセント学院", 23, 162, 8, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 101801, "B", 52, 14, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 14, "魔族", "伊藤静");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("お歌もにんじんも、ウサギさんも大好き♪", "ミミ", "リトルリリカル", 10, 117, 4, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 102001, "O", 21, 3, 0, "かわいいもの集め", 5, "獣人族", "日高里菜");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("泣き虫で臆病な守ってあげたい女の子", "クルミ", "サレンディア救護院", 12, 150, 6, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 102101, "B", 40, 9, 0, "観劇、おままごと", 9, "ヒューマン", "植田佳奈");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人見知りであまのじゃくな女の子", "ヨリ", "悪魔偽王国軍（ディアボロス）", 13, 150, 11, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 102201, "O", 40, 22, 0, "ゲーム全般", 7, "魔族", "原紗友里");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ぷうきちといつも一緒！", "アヤネ", "サレンディア救護院", 14, 148, 5, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 102301, "B", 38, 10, 0, "屋内でできる遊び", 9, "ヒューマン", "芹澤優");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("お嬢さまのためにがんばるドジっ娘メイド", "スズメ", "サレンディア救護院", 15, 154, 12, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 102501, "O", 43, 12, 0, "ご奉仕", 9, "ヒューマン", "悠木碧");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("遊びと睡眠が何より大事なぐうたら娘", "リン", "牧場（エリザベスパーク）", 17, 144, 1, "test", 102601, "B", 42, 1, 0, "あんパン", 11, "獣人族", "小岩井ことり");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("運命の相手に一途すぎる乙女", "エリコ", "トワイライトキャラバン", 16, 154, 7, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 102701, "B", 43, 30, 0, "実験、裁縫、料理", 13, "魔族", "橋本ちなみ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("救護院を経営する優しい庶民派お嬢様", "サレン", "サレンディア救護院", 17, 156, 10, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 102801, "A", 43, 4, 0, "経営、お茶会", 9, "エルフ", "堀江由衣");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("歌って踊れる大人気アイドル", "ノゾミ", "カルミナ", 17, 157, 1, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 102901, "B", 40, 24, 0, "舞台鑑賞、ダンス", 4, "ヒューマン", "日笠陽子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("トーゴクの神秘、オシエテクダサイ！", "ニノン", "ヴァイスフリューゲル　ランドソル支部", 16, 163, 8, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 103001, "O", 51, 31, 0, "忍法開発", 15, "ヒューマン", "佐藤聡美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("占いが得意な霊能少女", "シノブ", "悪魔偽王国軍（ディアボロス）", 18, 157, 12, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 103101, "AB", 42, 22, 0, "占い", 7, "魔族", "大坪由佳");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("一人前の商人を目指すパワフルお嬢様", "アキノ", "メルクリウス財団", 18, 157, 3, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 103201, "AB", 45, 12, 0, "慈善事業", 12, "ヒューマン", "松嵜麗");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("みんなを笑顔にするお笑い牧場主", "マヒル", "牧場（エリザベスパーク）", 20, 142, 3, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 103301, "B", 35, 3, 0, "漫才", 11, "ヒューマン", "新田恵海");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("純情でほっとけない大人の女性", "ユカリ", "メルクリウス財団", 22, 164, 3, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 103401, "A", 55, 16, 0, "ウインドーショッピング", 12, "エルフ", "今井麻美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("礼儀正しくしっかり者のちびっ子優等生", "キョウカ", "リトルリリカル", 8, 118, 2, "test", 103601, "A", 21, 2, 0, "お勉強", 5, "エルフ", "小倉唯");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("義理堅くてからかい好きな剣術少女", "トモ", "王宮騎士団（NIGHTMARE）", 13, 149, 8, "test", 103701, "A", 43, 11, 0, "剣術、年長者をからかう", 8, "ヒューマン", "茅原実里");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("読書が趣味の病弱少女", "シオリ", "牧場（エリザベスパーク）", 14, 153, 11, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 103801, "A", 40, 3, 0, "読書、お散歩", 11, "獣人族", "小清水亜美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("「友達」に憧れる、エルフの森の女の子", "アオイ", "フォレスティエ", 13, 158, 6, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 104001, "AB", 44, 6, 0, "友達作りのイメトレ", 6, "エルフ", "花澤香菜");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人々を守るために歌う、唱喚士の少女", "チカ", "カルミナ", 17, 163, 6, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 104201, "O", 46, 3, 0, "各種楽器", 4, "ヒューマン", "福原綾香");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("男勝りで情に厚いワイルド娘", "マコト", "自警団（カォン）", 17, 168, 8, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 104301, "O", 54, 9, 0, "お菓子作り", 10, "獣人族", "小松未可子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("かつては夜を支配した最強の吸血鬼", "イリヤ", "悪魔偽王国軍（ディアボロス）", "??", 172, 5, "test", 104401, "A", 50, 5, 0, "世界征服", 7, "魔族", "丹下桜");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("妄想大好き！　ほんとは照れ屋な女の子", "クウカ", "ヴァイスフリューゲル　ランドソル支部", 18, 157, 11, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 104501, "AB", 49, 19, 0, "小説を読むこと", 15, "ヒューマン", "長妻樹里");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("弱きを助け強きをくじく猫娘", "タマキ", "メルクリウス財団", 19, 158, 3, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 104601, "AB", 48, 1, 0, "猫とたわむれること", 12, "獣人族", "沼倉愛美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("素顔を見せない冷静沈着な女性騎士", "ジュン", "王宮騎士団（NIGHTMARE）", 25, 171, 10, "？？？", 104701, "A", 50, 25, 0, "格闘技、湯浴み", 8, "ヒューマン", "川澄綾子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("仕事も私事も効率優先な傭兵少女", "ミフユ", "メルクリウス財団", 20, 163, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 104801, "O", 49, 11, 0, "傭兵などのアルバイト", 12, "ヒューマン", "田所あずさ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("お姉ちゃんがお世話してあげるからねっ！", "シズル", "ラビリンス", 18, 168, 10, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 104901, "O", 54, 24, 0, "家事全般", 3, "ヒューマン", "生天目仁美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ちょっとおませな恋に恋する女の子", "ミサキ", "ルーセント学院", 11, 120, 1, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 105001, "A", 22, 3, 0, "ファッション誌鑑賞、コスメ集め", 14, "魔族", "久野美咲");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("実験が趣味の危険な科学者", "ミツキ", "トワイライトキャラバン", 27, 166, 3, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 105101, "A", 53, 7, 0, "研究、実験", 13, "ヒューマン", "三石琴乃");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("乙女チックなもふもふアニマル", "リマ", "牧場（エリザベスパーク）", 17, 150, 3, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 105201, "A", 100, 14, 0, "毛繕い、お喋り", 11, "獣人族", "徳井青空");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("見た目も中身もお子ちゃまな異国の軍人", "モニカ", "ヴァイスフリューゲル　ランドソル支部", 17, 140, 7, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 105301, "A", 33, 28, 0, "お菓子屋通い", 15, "ヒューマン", "辻あゆみ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ファッション大好きなキュートガール", "ツムギ", "カルミナ", 14, 153, 9, "test", 105401, "AB", 45, 7, 0, "裁縫", 4, "ヒューマン", "木戸衣吹");
