INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("空への冒険を夢見る騎空士の少女", "ジータ", "？？？", 17, 156, 3, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 105701, "O", 45, 10, 0, "冒険、おしゃべり", "", "ヒューマン", "金元寿子");
