INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("弱きを助け強きをくじく猫娘", "タマキ（サマー）", "メルクリウス財団", 19, 158, 3, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 107901, "AB", 48, 1, 0, "猫とたわむれること", 12, "獣人族", "沼倉愛美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("仕事も私事も効率優先な傭兵少女", "ミフユ（サマー）", "メルクリウス財団", 20, 163, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 108001, "O", 49, 11, 0, "傭兵などのアルバイト", 12, "ヒューマン", "田所あずさ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("占いが得意な霊能少女", "シノブ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 18, 157, 12, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 108101, "AB", 42, 22, 0, "占い", 7, "魔族", "大坪由佳");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("プリン大好きゴースト娘", "ミヤコ（ハロウィン）", "悪魔偽王国軍（ディアボロス）", 14, 130, 1, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 108201, "B", 32, 23, 0, "プリンを食べること", 7, "魔族", "雨宮天");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ちょっとおませな恋に恋する女の子", "ミサキ（ハロウィン）", "ルーセント学院", 11, 120, 1, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 108301, "A", 22, 3, 0, "ファッション誌鑑賞、コスメ集め", 14, "魔族", "久野美咲");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人々を守るために歌う、唱喚士の少女", "チカ（クリスマス）", "カルミナ", 17, 163, 6, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 108401, "O", 46, 3, 0, "各種楽器", 4, "ヒューマン", "福原綾香");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("泣き虫で臆病な守ってあげたい女の子", "クルミ（クリスマス）", "サレンディア救護院", 12, 150, 6, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 108501, "B", 40, 9, 0, "観劇、おままごと", 9, "ヒューマン", "植田佳奈");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ぷうきちといつも一緒！", "アヤネ（クリスマス）", "サレンディア救護院", 14, 148, 5, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 108601, "B", 38, 10, 0, "屋内でできる遊び", 9, "ヒューマン", "芹澤優");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人助けが大好き！　前向き格闘娘", "ヒヨリ（ニューイヤー）", "トゥインクルウィッシュ", 16, 155, 8, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 108701, "A", 44, 27, 0, "人助け、応援", 2, "獣人族", "東山奈央");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("戦闘のサポートが得意な、心優しい少女", "ユイ（ニューイヤー）", "トゥインクルウィッシュ", 17, 158, 4, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 108801, "O", 47, 5, 0, "料理、人間観察", 2, "ヒューマン", "種田梨沙");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("クールで何事にも真っ直ぐな剣士", "レイ（ニューイヤー）", "トゥインクルウィッシュ", 18, 163, 1, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 108901, "B", 46, 12, 0, "読書、乗馬、お茶", 2, "魔族", "早見沙織");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("運命の相手に一途すぎる乙女", "エリコ（バレンタイン）", "トワイライトキャラバン", 16, 154, 7, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 109001, "B", 43, 30, 0, "実験、裁縫、料理", 13, "魔族", "橋本ちなみ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("お姉ちゃんがお世話してあげるからねっ！", "シズル（バレンタイン）", "ラビリンス", 18, 168, 10, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 109101, "O", 54, 24, 0, "家事全般", 3, "ヒューマン", "生天目仁美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("英霊と契約を結んだマナリアの天才王女", "アン", "？？？", 17, 156, 12, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 109201, "AB", 55, 1, 0, "読書", "", "ヒューマン", "日笠陽子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("マナリア魔法学院の新入生", "ルゥ", "？？？", 16, 144, 2, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 109301, "O", 45, 4, 0, "食べること、眠ること", "", "ヒューマン", "こやまきみこ");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人を超越した力を有す心優しい竜姫", "グレア", "？？？", 17, 167, 11, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 109401, "B", 67, 3, 0, "ピアノ", "", "半人半竜", "福原綾香");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("妄想大好き！　ほんとは照れ屋な女の子", "クウカ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 18, 157, 11, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 109501, "AB", 49, 19, 0, "小説を読むこと", 15, "ヒューマン", "長妻樹里");
