INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("マホマホ王国のプリンセス", "マホ（シンデレラ）", "自警団（カォン）", 16, 155, 9, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 116001, "O", 42, 22, 0, "空想、ぬいぐるみ集め", 10, "獣人族", "内田真礼");
