INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("弱きを助け強きをくじく猫娘", "タマキ（作業服）", "メルクリウス財団", 19, 158, 3, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 116801, "AB", 48, 1, 0, "猫とたわむれること", 12, "獣人族", "沼倉愛美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("仕事も私事も効率優先な傭兵少女", "ミフユ（作業服）", "メルクリウス財団", 20, 163, 11, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 116901, "O", 49, 11, 0, "傭兵などのアルバイト", 12, "ヒューマン", "田所あずさ");
