INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("お姉ちゃんがお世話してあげるからねっ！", "シズル（サマー）", "ラビリンス", 18, 168, 10, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 117101, "O", 54, 24, 0, "家事全般", 3, "ヒューマン", "生天目仁美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("歌って踊れる大人気アイドル", "ノゾミ（サマー）", "カルミナ", 17, 157, 1, "", 117201, "B", 40, 24, 0, "舞台鑑賞、ダンス", 4, "ヒューマン", "日笠陽子");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人々を守るために歌う、唱喚士の少女", "チカ（サマー）", "カルミナ", 17, 163, 6, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 117301, "O", 46, 3, 0, "各種楽器", 4, "ヒューマン", "福原綾香");
