INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("実験が趣味の危険な科学者", "ミツキ（オーエド）", "トワイライトキャラバン", 27, 166, 3, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 117501, "A", 53, 7, 0, "研究、実験", 13, "ヒューマン", "三石琴乃");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("ボクは誰よりも美しい", "ユキ（オーエド）", "ヴァイスフリューゲル　ランドソル支部", 14, 150, 10, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 117601, "AB", 40, 10, 0, "鏡で自分を見ること", 15, "エルフ", "大空直美");
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("いつでも「なんくるないさ～」な天然娘", "カオリ（ハロウィン）", "自警団（カォン）", 17, 158, 7, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 117701, "A", 53, 7, 0, "踊り、空手", 10, "獣人族", "高森奈津美");
