INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("前世を信じる中二病患者、「疾風の冥姫」", "アンナ（パイレーツ）", "トワイライトキャラバン", 17, 159, 7, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 121901, "A", 45, 5, 0, "小説執筆", 13, "魔族", "髙野麻美");
