INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("人助けが大好き！　前向き格闘娘", "ヒヨリ（サマー）", "トゥインクルウィッシュ", 16, 155, 8, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 122401, "A", 44, 27, 0, "人助け、応援", 2, "獣人族", "東山奈央");
